// ─── Intent Classification ──────────────────────────────────────────────────

type UserIntent =
  | 'data_logging'      // "вешу 85", "съел гречку", "выпил воду"
  | 'program_creation'  // "составь программу", "план на неделю"
  | 'workout_modify'    // "сделай легче", "убери упражнение"
  | 'technique_question'// "как делать присед", "техника жима"
  | 'nutrition_query'   // "сколько белка", "рассчитай КБЖУ"
  | 'analytics_query'   // "как мой прогресс", "покажи статистику"
  | 'greeting'          // "привет", "здорово"
  | 'complaint'         // "болит", "травма", "не могу"
  | 'motivation'        // "не хочу", "лень", "скучно"
  | 'general';          // всё остальное

interface IntentConfig {
  temperature: number;
  maxTokens: number;
  toolsEnabled: boolean;  // false = chatWithoutTools (faster, cheaper for info-only queries)
  priorityModules?: string[]; // force-include these knowledge modules
}

const INTENT_CONFIGS: Record<UserIntent, IntentConfig> = {
  data_logging:       { temperature: 0.3, maxTokens: 3072, toolsEnabled: true },
  program_creation:   { temperature: 0.6, maxTokens: 8192, toolsEnabled: true },
  workout_modify:     { temperature: 0.3, maxTokens: 4096, toolsEnabled: true },
  technique_question: { temperature: 0.5, maxTokens: 4096, toolsEnabled: true, priorityModules: ['EXERCISE_TECHNIQUE'] },
  nutrition_query:    { temperature: 0.4, maxTokens: 4096, toolsEnabled: true, priorityModules: ['NUTRITION', 'NUTRITION_DATABASE'] },
  analytics_query:    { temperature: 0.4, maxTokens: 4096, toolsEnabled: true },
  greeting:           { temperature: 0.7, maxTokens: 1024, toolsEnabled: true },
  complaint:          { temperature: 0.4, maxTokens: 4096, toolsEnabled: true, priorityModules: ['INJURY_AND_REHAB', 'RECOVERY'] },
  motivation:         { temperature: 0.7, maxTokens: 3072, toolsEnabled: true, priorityModules: ['PSYCHOLOGY'] },
  general:            { temperature: 0.5, maxTokens: 6144, toolsEnabled: true },
};

const INTENT_PATTERNS: Array<[UserIntent, RegExp[]]> = [
  ['data_logging', [
    /(?:вешу|вес\s*\d|взвеси|записать?\s*вес|мой\s*вес\s*\d)/i,
    /(?:съел[аи]?|поел[аи]?|кушал|завтрак|обед|ужин|перекус).*(?:\d|грамм|порц|тарелк)/i,
    /(?:выпил[аи]?|пил[аи]?)\s*(?:вод|стакан|бутылк|чай|кофе|литр|\d)/i,
    // Round 223: dropped \b — JS \b is ASCII-only, doesn't fire between
    // Cyrillic and whitespace, so "съел " never matched. Anchor instead
    // by trailing whitespace OR end of string.
    /(?:съел[аи]?|поел[аи]?|кушал[аи]?)(?:$|[\s.,!?])/i,
    // "ел 200г", "ела курицу" — bare past tense "есть" with food/quantity context
    /(?:^|[\s,.])ел[аи]?\s+(?:\d|грамм|курицу?|мясо|рыбу?|рис|гречку?|творог|яйца?|кашу?|хлеб|бутерброд|суп|салат|протеин)/i,
    /(?:удали|убери)\s*(?:приём|завтрак|обед|ужин|перекус|еду)/i,
    /(?:рост|мне)\s*\d{2,3}\s*(?:см|кг)/i,
    // Body measurements — use stem matches to handle Russian case inflections (талию, груди, бёдер...)
    /(?:замерил[аи]?|измерил[аи]?)\s*(?:тали|груд|бёдр|бицепс|шею?|икр|бедр|плечи?|пояс|предплечь)/i,
    /(?:тали[яюи]|обхват\s*(?:тали|груд|плеч)|груд[ьи]|бёдр[ао]?|бицепс|шею?|икр[ыа]?|бедр[оа]?|поясниц[аы]?|предплечь[еяи]?)\s*[\d.,]/i,
    /^\d{2,3}(?:[.,]\d)?\s*(?:кг|kg)\s*$/i,
    /(?:сегодня|утром|вчера)\s*(?:вес|вешу|взвесил[ся]?)\s*\d/i,
    /(?:записать?|добавить?|внести|залогировать?)\s*(?:замер|измерен|сон|кардио|пробежк|плавание|питание|приём\s*пищи)/i,
    /(?:выпил[аи]?|пил[аи]?)\s*(?:воды?|воду)\s*\d/i,
    /(?:логировать|залогировать|добавить?\s*приём)/i,
    /(?:спал[аи]?|поспал[аи]?|лёг\s*в|лег\s*в|встал\s*в|проснул[ся]*\s*в)\s*\d/i,
    /\d+\s*час(?:ов|а)?\s*(?:сна|спал|поспал)/i,
    // Cardio logging
    /(?:бежал[аи]?|пробежал[аи]?|пробежк[аи]?|бегал[аи]?)\s*\d/i,
    /(?:ехал[аи]?|катался?|поехал|вело(?:сипед)?|вел(?:ик)?|велотренажёр)\s*\d/i,
    /(?:плавал[аи]?|поплавал[аи]?|бассейн)\s*\d/i,
    /(?:кардио|cardio)\s*(?:сделал[аи]?|выполнил[аи]?|записать?|\d)/i,
    /\d+\s*мин(?:ут)?\s*(?:бег[аа]?|кардио|вело|бежал|плавани)/i,
    // "на завтрак/обед/ужин ел/было/было" — meal reporting without explicit verb
    /(?:на\s*завтрак|на\s*обед|на\s*ужин|на\s*перекус)\s+(?:ел[аи]?|поел[аи]?|съел[аи]?|было?|был[аи]?|выпил[аи]?|перекусил[аи]?)/i,
    // Round 102: explicit memory commands. Falling through to update_memory
    // tool dispatch when the LLM picks it up. Without this hint these
    // sentences classified as 'general' which still has tools enabled
    // but no priority modules — the LLM was less reliably choosing the
    // memory tool.
    /(?:запомни|запиши\s*в\s*память|сохрани\s*факт)/i,
    /(?:забудь(?:\s*про|\s*о)?|удали\s*из\s*памяти|сотри\s*факт)/i,
    // Round 155: alternative memory phrasings — "помни про X", "помни что",
    // "не забывай" — equivalent intent.
    /(?:помни\s*(?:про|о|что))/i,
    /(?:не\s*забывай(?:\s*про|\s*что|\s*о)?)/i,
  ]],
  ['program_creation', [
    /(?:составь|создай|сделай|придумай|напиши|разработай)\s*(?:програм|план|сплит|тренировк)/i,
    /(?:программ[ау]?\s*(?:на|для|тренировок))/i,
    /(?:план\s*(?:на\s*недел|тренировок))/i,
    // AI-5: negative lookbehind so "не хочу тренироваться" stays in
    // motivation, not program_creation.
    /(?<!не\s)(?:хочу\s*(?:начать|заниматься|тренировать))/i,
    /(?:расписание\s*тренировок)/i,
    /(?:новую?\s*программу|сплит\s*(?:на|для))/i,
    /(?:хочу\s*(?:программу|план|сплит))/i,
    /(?:помоги\s*(?:с\s*)?(?:программой|планом\s*тренировок))/i,
    /(?:программа\s*(?:для|на)\s*\d)/i,
  ]],
  ['workout_modify', [
    /(?:сделай|давай)\s*(?:легче|тяжелее|проще|сложнее)/i,
    /(?:убери|удали|замени|поменяй|добавь)\s*(?:упражнен|подход|сет)/i,
    /(?:не могу делать|болит при|замена для)/i,
    /(?:увеличь|уменьши|снизь|подними)\s*(?:вес|нагрузк|повтор|подход)/i,
    /(?:поменяй|замени|свопни)\s*(?:жим|присед|тяг|упражнение)/i,
    // Round 104: widen verb→noun pairing so "убери жим", "убери становую",
    // "убери приседания" all route to workout_modify. The original pattern
    // required упражнен/подход/сет after the verb — too narrow for natural
    // Russian. Now we accept canonical lift nouns directly.
    /(?:убери|удали|замени|поменяй)\s*(?:жим|присед|тяг|становую|становой|разведен|подъ[её]м|румын|гак)/i,
    /(?:добавь|включи)\s*(?:суперсет|суперсеты)/i,
    /(?:переставь|переупорядочи|измени\s*порядок)\s*(?:упражнен)/i,
    // Round 223: replaced \w+ with [а-яё]+ — JS \w excludes Cyrillic so
    // "тренировку" / "плана" never matched.
    /(?:активируй|включи|запусти|начни|переключись\s*на)\s*(?:программу?|трен[а-яё]+)/i,
    /(?:хочу\s*(?:начать|запустить))\s+(?:iron|программу|пл[а-яё]+)/i,
    /(?:удали|убери)\s*(?:программу|план|тренировочный\s*план)/i,
  ]],
  ['technique_question', [
    /(?:как\s*(?:делать|правильно|выполнять|научиться))/i,
    /(?:техник[аеу]?\s*(?:выполнения|жим|присед|тяг|упражнен))/i,
    // Round 104: widen "техника <X тяги/жима/приседа>" so "техника
    // становой тяги" / "техника подтягивания" / "техника румынской тяги"
    // match. Original pattern required the lift root immediately after
    // "техника"; widened to allow up to 2 noun-phrase tokens between.
    //
    // NB: dropped the \b after "техник[аеу]?" because JS \b is ASCII-only
    // — it doesn't fire between Cyrillic word chars and whitespace, so
    // "техника становой" never matched. Without \b the rest of the regex
    // is anchored by the literal Cyrillic match anyway.
    /(?:техник[аеу]?)[\sа-яё-]{0,30}?(?:жим|присед|тяг|подтягиван|становой|становую|румын|подъ[её]м|разведен|выпад)/i,
    /(?:покажи|объясни|расскажи)\s*(?:технику|как делать)/i,
    /(?:ошибк[иа]\s*(?:в|при|на)\s*(?:жим|присед|тяг))/i,
    /(?:чем\s*заменить|аналог|альтернатив)/i,
    /(?:правильная?\s*постановка|форм[ао]\s*(?:в|при|на))/i,
    // Breathing, tempo, ROM, grip — commonly asked technique sub-topics
    /(?:дыхани[ея]\s*(?:при|во\s*время|в)|как\s*дышать)/i,
    /(?:глубин[аыу]\s*(?:приседа|приседания)|нужно\s*ли\s*(?:касать|доходить|опускать))/i,
    /(?:хват|ширин[аыу]\s*(?:постановки|хвата|ног|рук|стоп|плеч))/i,
    /(?:темп|скорость\s*(?:выполнения|движения|подъёма|опускания))/i,
    /(?:почему\s*(?:нельзя|важно|нужно)\s*(?:не\s*)?(?:округлять|прогибать|сгибать|удерживать))/i,
    /(?:(?:приседать|жать|тянуть|подтягиваться)\s*правильно)/i,
  ]],
  ['nutrition_query', [
    /(?:сколько\s*(?:белк|калори|жир|углевод|есть|пить|нужно\s*(?:есть|белк|калори)))/i,
    /(?:рассчитай|посчитай|расчёт)\s*(?:кбжу|калори|tdee|бжу|норм)/i,
    /(?:что\s*(?:есть|кушать|поесть|приготовить))/i,
    /(?:меню|рацион|диет[аеу])\s/i,
    /(?:кбжу|бжу|калорийность|макрос)/i,
    /(?:полезно|вредно)\s*(?:ли\s*)?(?:есть|кушать|пить)/i,
    /(?:сколько\s*калорий?\s*в)/i,
    /(?:белк[а-я]*|протеин[а-я]*)\s*(?:для|на\s*кг|сколько)/i,
    /(?:дефицит|профицит)\s*калорий/i,
    /(?:что\s*(?:съесть|поесть|перекусить))\s*(?:до|после|перед|между)/i,
    /(?:питание\s*(?:до|после|вокруг|перед|при|для)\s*тренировк)/i,
    /(?:похудеть|сбросить\s*(?:вес|кг))\s*(?:с\s*помощью\s*питания?|через\s*диет)/i,
    /(?:набрать\s*(?:массу|мышцы))\s*(?:питание|через\s*еду)/i,
  ]],
  ['analytics_query', [
    /(?:как\s*(?:мой|мои|у\s*меня)\s*(?:прогресс|результат|успехи|динамик))/i,
    /(?:покажи|расскажи|скажи)\s*(?:статистик|прогресс|результат|аналитик)/i,
    // AI-5: was `мой[и]?` which matches "мой" / "мойи" but NOT "мои" (plural).
    // Russian users say "мои рекорды" (plural) more often; add proper plural.
    /(?:мо(?:й|и)\s*(?:рекорд|pr|пм|1пм|достижени))/i,
    /(?:что\s*(?:изменилось|улучшилось))/i,
    /(?:за\s*(?:последни[йх]?\s*)?(?:месяц|неделю|год|период|время))\s*(?:тренировок|результат|прогресс|изменен)/i,
    /(?:история\s*(?:тренировок|упражнений|весов?|питания))/i,
    /(?:мой[аи]?\s*(?:прогресс|статистика|результат|аналитика))/i,
    /(?:как\s*рос|динамика\s*(?:веса|жима|присед|тяги|результатов))/i,
    /(?:насколько)\s*(?:я\s*)?(?:вырос|прибавил|улучшил[ся]?|прогрессировал)/i,
    // AI-5: allow optional "я" between "сколько" and the verb so
    // "сколько я жму" (natural Russian) routes to analytics.
    /(?:сколько(?:\s+я)?\s*(?:жму|приседаю|тяну|жал|приседал|тянул))/i,
    /(?:мои?\s*силовые|мои?\s*показатели|мои?\s*цифры)/i,
    /(?:оцени|оценка)\s*(?:мой[аи]?\s*)?(?:прогресс|форм[ау]|подготовк|тренировок)/i,
  ]],
  ['greeting', [
    // Round 223: \w+ → [а-яё]+ for "доброе утро" / "добрый день" matching
    /^(?:привет|здравствуй|здорово|хай|хэй|hi|hello|добр[а-яё]+\s*(?:утро|день|вечер)|йо|ку)\s*[!.?]?\s*$/i,
    /^(?:как\s*дела|что\s*нового|как\s*ты|что\s*скажешь|что\s*как)\s*[!.?]?\s*$/i,
    /^(?:привет[,!]?\s*(?:как\s*дела|что\s*нового|как\s*ты))\s*[!.?]?\s*$/i,
  ]],
  ['complaint', [
    /(?:болит|боль\s|травм|повредил|ушиб|растян|разры|защемил|онемен|хруст|щёлк|щелк)/i,
    /(?:не\s*могу\s*(?:делать|тренироват|поднять|согнуть|разогнуть))/i,
    /(?:дискомфорт|воспален|опух)/i,
    /(?:перетренировал[ся]?|переусерд|слишком\s*сильно\s*(?:болят|ломит))/i,
  ]],
  ['motivation', [
    /(?:не\s*хочу|лень|надоело|скучно|устал[аи]?|бросить|пропустил|нет\s*(?:сил|мотивац|желани))/i,
    /(?:заставить\s*себя|как\s*(?:мотивировать|заставить|начать))/i,
    /(?:потерял\s*(?:мотивац|интерес|запал))/i,
    /(?:не\s*вижу\s*результатов|зачем\s*(?:тренировать|заниматься)|нет\s*прогресса)/i,
    /(?:выгорани|демотивирован|опустил\s*руки)/i,
    // Return after break, failure mindset, wanting to quit
    /(?:давно\s*не\s*(?:тренировал|занимал|ходил))/i,
    /(?:хочу\s*бросить|хочу\s*всё\s*бросить|думаю\s*бросить)/i,
    /(?:ничего\s*не\s*получается|не\s*верю\s*в\s*себя|сомневаюсь\s*(?:в\s*себе|что))/i,
    /(?:напомни\s*(?:мне\s*)?зачем|зачем\s*мне\s*(?:это|тренировать|заниматься))/i,
    /(?:не\s*(?:смог|получилось|вышло)\s*(?:сделать|выполнить|потренироваться))/i,
    /(?:плохое\s*(?:настроение|состояние|самочувствие))\s*(?:и\s*)?(?:не\s*хочу|но|поэтому)/i,
  ]],
];

/**
 * Fast rule-based intent classifier. No AI call — pure regex.
 * Returns the most specific intent or 'general' as fallback.
 */
// Exported for unit testing in __tests__/classifyIntent.test.ts. Not used
// directly by external consumers; the route imports it locally.
export function classifyIntent(message: string): UserIntent {
  for (const [intent, patterns] of INTENT_PATTERNS) {
    if (patterns.some((p) => p.test(message))) {
      return intent;
    }
  }
  return 'general';
}

// ─── Emotion Detection ──────────────────────────────────────────────────────

type UserMood = 'frustrated' | 'excited' | 'anxious' | 'sad' | 'neutral' | 'curious' | 'fatigued' | 'demotivated';

interface MoodDirective {
  mood: UserMood;
  directive: string; // injected into system prompt
}

const MOOD_PATTERNS: Array<[UserMood, RegExp[]]> = [
  ['frustrated', [
    /(?:за[ае]бал|бесит|достало|надоело|ненавижу|сука|блять|бл[яе]|пиздец|хуй|нахуй)/i,
    /(?:ничего не (?:работает|получается|помогает|меняется))/i,
    /(?:я\s*(?:устал|задолбал|замучил)(?:ся|ась)?)/i,
    /(?:какого\s*(?:хрена|чёрта|хера|фига))/i,
    /(?:сколько можно|опять|снова)\s*(?:одно и то же|ничего)/i,
  ]],
  ['excited', [
    /(?:ура|ааа|оооо|вау|круто|офигеть|охренеть|обалдеть|класс|супер|бомба)/i,
    /(?:наконец[-\s]?то|я\s*(?:смог|сделал|осилил|поднял|побил))/i,
    // Round 107 fix: bare "пр" / "пб" (PR / PB abbreviations) used to
    // match inside any word containing those letters together — e.g.
    // "справлюсь" contains "пр" and was tagged excited. Now require
    // explicit word boundaries (start of string / whitespace before;
    // end of string / whitespace / punctuation after).
    /(?:новый рекорд|личный рекорд|(?:^|\s)(?:pr|пр|пб)(?:$|\s|[.,!?]))/i,
    /(?:!!|🔥|💪|🎉|🏆)/,
  ]],
  ['anxious', [
    /(?:боюсь|страшно|опасно ли|вредно ли|не навредит|не опасно)/i,
    /(?:переживаю|волнуюсь|тревож|беспокоюсь)/i,
    /(?:а вдруг|а что если|не (?:сломаю|порву|повредю|надорву))/i,
    /(?:стоит ли|можно ли|безопасно ли|нормально ли)/i,
  ]],
  ['sad', [
    /(?:грустно|печально|расстроен|депрессия|уныние|тоска)/i,
    /(?:ничего не выходит|я\s*(?:неудачник|жирный|слабый|бесполезн))/i,
    /(?:зачем\s*(?:всё это|я\s*(?:вообще|тут)|стараюсь))/i,
    /(?:все\s*(?:лучше|сильнее|красивее)\s*(?:меня|чем я))/i,
  ]],
  // Round 126: 'demotivated' — distinct from 'sad' (depression),
  // 'frustrated' (anger), and 'fatigued' (physical exhaustion). It's
  // motivational lethargy: "лень", "не хочу", "забил", "неохота".
  // The right response is small-step framing + identity / habit cues,
  // NOT consoling (sad) or recovery talk (fatigued).
  ['demotivated', [
    /(?:лень\s*(?:идти|ехать|тренироват|качат))/i,
    /(?:не\s*хочется|неохот|забил\s*на\s*зал|забил\s*на\s*тренировк)/i,
    /(?:не\s*могу\s*заставить\s*себя|не\s*могу\s*начать)/i,
    /(?:скучно\s*(?:в\s*зале|тренироват)|надоело\s*тренироват)/i,
  ]],
  // Round 106: 'fatigued' mood — distinct from 'frustrated' (anger) and
  // 'sad' (depression). Captures physical/CNS exhaustion that should
  // trigger a recovery / deload conversation, not a motivation pep talk.
  // Common phrasings: "выгораю", "нет сил", "ноги ватные", "вяло",
  // "перетренировался", "устал как собака".
  ['fatigued', [
    // Round 223: \w* → [а-яё]* for Cyrillic-only stem matching.
    // Examples: "выгораю", "перегорел", "перетренировался", "перегружен"
    /(?:выгора[а-яё]*|перегора[а-яё]*|перетренир[а-яё]*|перегруз[а-яё]*)/i,
    /(?:нет\s*сил|без\s*сил|на\s*нул[её]|обессилел)/i,
    /(?:устал\s*как\s*(?:собака|чёрт|пёс)|выжат\s*как\s*лимон)/i,
    /(?:ноги\s*ватные|вял[а-яё]*|разбит[ыа]?|туман\s*в\s*голове)/i,
    /(?:нагрузк[аи]\s*(?:слишком|очень)\s*(?:большая|много)|устал\s*от\s*тренир)/i,
  ]],
  ['curious', [
    /(?:а\s*(?:почему|зачем|как так|правда ли))/i,
    /(?:интересно|хочу\s*(?:узнать|понять|разобраться))/i,
    /(?:объясни|расскажи подробнее|а что насчёт|в чём разница)/i,
    /(?:\?.*\?)/,  // multiple question marks = curiosity
  ]],
];

const MOOD_DIRECTIVES: Record<UserMood, string> = {
  frustrated: '⚡ НАСТРОЕНИЕ ПОЛЬЗОВАТЕЛЯ: раздражён/фрустрирован. Будь максимально конкретным, без воды. Покажи эмпатию ("Понимаю, это бесит"), но сразу дай решение. Не морализируй.',
  excited: '🎉 НАСТРОЕНИЕ ПОЛЬЗОВАТЕЛЯ: воодушевлён/рад. Поддержи энергию! Похвали конкретное достижение через данные. Предложи следующий вызов чтобы не терять момент.',
  anxious: '🫶 НАСТРОЕНИЕ ПОЛЬЗОВАТЕЛЯ: тревожится/переживает. Успокой фактами и наукой. Объясни риски честно но без запугивания. Дай чёткий безопасный план действий.',
  sad: '💪 НАСТРОЕНИЕ ПОЛЬЗОВАТЕЛЯ: подавлен/грустит. Будь мягким но не жалей. Покажи прогресс через данные ("посмотри сколько ты уже сделал"). Дай маленький достижимый шаг на сегодня.',
  neutral: '',
  curious: '🧠 НАСТРОЕНИЕ ПОЛЬЗОВАТЕЛЯ: любопытен, хочет разобраться. Дай развёрнутый ответ с объяснением механизмов. Можно чуть подробнее чем обычно — человек хочет понять.',
  // Round 106: fatigued is recovery-related, not motivation-related. The
  // worst response here is "ты можешь!" — that ignores the signal. Push
  // toward deload / sleep / recovery talk first.
  fatigued: '😴 НАСТРОЕНИЕ ПОЛЬЗОВАТЕЛЯ: физически вымотан / признаки выгорания. НЕ давай моралите про "терпи и работай". Сначала проверь: сон, объём за последнюю неделю, давность последней неделя отдыха. Если ACWR > 1.5 — предложи деload. Подскажи 2-3 практики восстановления (сон, белок, растяжка). Тренировку — только лёгкую или совсем пропустить.',
  // Round 126: demotivated is mental, not physical. NOT "ты устал, отдохни"
  // (that's fatigued). Use micro-commitment + identity framing.
  demotivated: '🪜 НАСТРОЕНИЕ ПОЛЬЗОВАТЕЛЯ: лень / нет мотивации (не путать с физической усталостью!). НЕ заставляй и не ругай. Предложи микро-шаг: "начни с 1 подхода, потом увидишь" / "5 минут — и можешь уйти". Напомни про identity ("ты тот, кто тренируется"). Если есть streak — упомяни конкретно сколько дней подряд. Лучше короткая 15-мин тренировка чем пропуск.',
};

// Exported for unit testing (round 107). Not used externally; the route
// imports it locally.
export function detectMood(message: string): MoodDirective {
  for (const [mood, patterns] of MOOD_PATTERNS) {
    if (patterns.some((p) => p.test(message))) {
      return { mood, directive: MOOD_DIRECTIVES[mood] };
    }
  }
  return { mood: 'neutral', directive: '' };
}

// ─── Time-Aware Context ─────────────────────────────────────────────────────

// Exported for unit testing (round 165).
export function getTimeContext(clientHour?: number, clientDate?: string): string {
  const now = new Date();
  const hour = clientHour ?? now.getHours();
  const DAY_NAMES = ['воскресенье', 'понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота'];
  // Use client-provided date for day-of-week/date string to avoid server-timezone mismatch
  const refDate = clientDate ? new Date(clientDate + 'T12:00:00.000Z') : now;
  const dayName = DAY_NAMES[refDate.getDay()];
  const dateStr = clientDate
    ? refDate.toLocaleDateString('ru-RU')
    : now.toLocaleDateString('ru-RU');

  let timeOfDay: string;
  let timeHint: string;
  if (hour >= 5 && hour < 10) {
    timeOfDay = 'утро';
    timeHint = 'Утро — хорошее время для тренировки натощак (кардио) или после лёгкого завтрака. Напомни про завтрак если нет записей.';
  } else if (hour >= 10 && hour < 14) {
    timeOfDay = 'первая половина дня';
    timeHint = 'Пик работоспособности. Хорошее время для силовой тренировки.';
  } else if (hour >= 14 && hour < 17) {
    timeOfDay = 'день';
    timeHint = 'Температура тела максимальна — оптимальное время для тяжёлых базовых упражнений и рекордов.';
  } else if (hour >= 17 && hour < 21) {
    timeOfDay = 'вечер';
    timeHint = 'Если пользователь ещё не тренировался сегодня — это последний шанс. Если тренировался — спроси как прошло.';
  } else {
    // All hours 0-23 covered by the if/else-if chain above (5-9, 10-13,
    // 14-16, 17-20, 21+ or <5). The final else is just hour >= 21 || hour
    // < 5 — kept as `else` for clarity. Round 146 cleanup: removed dead
    // branch that had `else if (hour >= 21 || hour < 5) ... else { ... }`
    // — the second else was unreachable since the elif covered every
    // remaining hour.
    timeOfDay = 'ночь';
    timeHint = 'Поздно для тренировки. Фокус на восстановление и сон. Если пользователь не спит — мягко напомни что сон = рост мышц.';
  }

  return `\n## ВРЕМЯ И ДАТА\nСейчас: ${dateStr}, ${dayName}, ${timeOfDay} (${hour}:${String(now.getMinutes()).padStart(2, '0')})\n${timeHint}`;
}

// ─── Profile Completeness Check ─────────────────────────────────────────────

interface ProfileGap {
  field: string;
  question: string;
  priority: number; // higher = ask sooner
}

// Exported for unit testing (round 164).
export function getProfileGaps(user: {
  weightKg: number | null;
  heightCm: number | null;
  goal: string | null;
  fitnessLevel: string | null;
  dateOfBirth: Date | null;
  gender: string | null;
  trainingExperienceYears: number | null;
} | null): ProfileGap[] {
  if (!user) return [];
  const gaps: ProfileGap[] = [];

  if (!user.weightKg) gaps.push({ field: 'вес', question: 'Сколько ты весишь? Это нужно для расчёта КБЖУ и нагрузки.', priority: 10 });
  if (!user.heightCm) gaps.push({ field: 'рост', question: 'Какой у тебя рост? Нужно для расчёта TDEE и ИМТ.', priority: 9 });
  if (!user.goal) gaps.push({ field: 'цель', question: 'Какая у тебя основная цель? Похудение, набор массы, сила, выносливость?', priority: 10 });
  if (!user.fitnessLevel) gaps.push({ field: 'уровень', question: 'Как давно тренируешься? Нужно чтобы подобрать правильную программу.', priority: 7 });
  if (!user.gender) gaps.push({ field: 'пол', question: 'Укажи пол — это влияет на нормы КБЖУ и рекомендации по тренировкам.', priority: 6 });
  if (!user.dateOfBirth) gaps.push({ field: 'возраст', question: 'Сколько тебе лет? Влияет на восстановление и допустимые нагрузки.', priority: 5 });
  if (!user.trainingExperienceYears) gaps.push({ field: 'стаж', question: 'Сколько лет занимаешься в зале? Или только начинаешь?', priority: 4 });

  return gaps.sort((a, b) => b.priority - a.priority);
}

// Maximum number of knowledge modules to include per request (controls token usage)
const MAX_KNOWLEDGE_MODULES = 4;

// Default modules for general/greeting messages that don't match any keywords
const DEFAULT_MODULES = ['TRAINING_PRINCIPLES', 'NUTRITION'];

// Pre-compute inverse document frequency for each keyword (rarer keywords = higher score)
// IDF = log(totalModules / modulesContainingKeyword) — keywords that appear in fewer modules are more discriminative
const KEYWORD_IDF_CACHE: Map<string, number> = new Map();
const TOTAL_MODULES = KEYWORD_MAPPINGS.length;

function getKeywordIDF(keyword: string): number {
  const cached = KEYWORD_IDF_CACHE.get(keyword);
  if (cached !== undefined) return cached;

  let modulesWithKeyword = 0;
  for (const [, keywords] of KEYWORD_MAPPINGS) {
    if (keywords.includes(keyword)) modulesWithKeyword++;
  }
  // IDF: rare keyword (1 module) = log(22/1) ≈ 3.1, common keyword (5 modules) = log(22/5) ≈ 1.5
  const idf = Math.log(TOTAL_MODULES / Math.max(1, modulesWithKeyword));
  KEYWORD_IDF_CACHE.set(keyword, idf);
  return idf;
}

// Pre-compute all IDFs at startup
for (const [, keywords] of KEYWORD_MAPPINGS) {
  for (const k of keywords) getKeywordIDF(k);
}

/**
 * The person's own calendar day, shifted back by `days`.
 *
 * SleepEntry.date and CardioSession.date are stamped with the CLIENT's local
 * date, so any query that compares against them has to use the client's clock.
 * Server UTC is a day behind for everyone east of Greenwich during their small
 * hours — which is exactly when someone asks how they slept.
 */
export function clientDayShift(clientDate: string | undefined, days: number): string {
  const base = clientDate && /^\d{4}-\d{2}-\d{2}$/.test(clientDate)
    ? clientDate
    : new Date().toISOString().slice(0, 10);
  if (days === 0) return base;
  return new Date(new Date(`${base}T00:00:00.000Z`).getTime() - days * 86400_000)
    .toISOString().slice(0, 10);
}

/**
 * The instant the user's current day began, on their clock.
 *
 * `clientTzOffsetMinutes` is signed minutes from UTC, matching the client's
 * `-getTimezoneOffset()`. Absent — an older build — it falls back to UTC,
 * which is the behaviour this replaces rather than a correct answer.
 */
export function dailyQuotaFloor(clientTzOffsetMinutes?: number): Date {
  const dayMs = 24 * 60 * 60 * 1000;
  const tzOffsetMs = (clientTzOffsetMinutes ?? 0) * 60 * 1000;
  const localNowMs = Date.now() + tzOffsetMs;
  return new Date(Math.floor(localNowMs / dayMs) * dayMs - tzOffsetMs);
}

/** Longer than this and a message is treated as carrying its own topic. */
const FOLLOW_UP_MAX_CHARS = 50;
/** Enough of the previous question to keep its keywords, not its essay. */
const CARRIED_CONTEXT_MAX_CHARS = 300;

/**
 * The text the ~1400 knowledge blocks are matched against.
 *
 * Each block gates itself on a keyword regex over the message. That works for
 * "стоит ли пить креатин?" and then fails on the very next turn: "а сколько
 * грамм?" carries no keyword, so the block switches off exactly when the
 * person is digging further into the topic they just raised — the model
 * answers the follow-up with less to go on than it had for the question.
 *
 * A follow-up that short cannot stand on its own, so it is matched together
 * with the question before it. Longer messages carry their own topic and are
 * left alone; otherwise every block from the previous turn would linger into
 * an unrelated question.
 */
export function buildTopicQuery(message: string, previousUserMessage: string): string {
  const trimmed = message.trim();
  const previous = previousUserMessage.trim();
  if (trimmed.length > FOLLOW_UP_MAX_CHARS || !previous) return message;
  return `${previous.slice(0, CARRIED_CONTEXT_MAX_CHARS)} ${message}`;
}

/**
 * TF-IDF-inspired knowledge module selection.
 * Improvements over simple keyword counting:
 * 1. IDF weighting: rare/specific keywords score higher than common ones
 * 2. Position bonus: keywords at the start of the message get a small boost
 * 3. Exact match bonus: full keyword match (not substring) scores higher
 * 4. Decay on recency: older messages contribute less
 * 5. Profile-based implicit relevance boosting
 * 6. Anti-overlap: penalize selecting modules with heavily overlapping topics
 */
/**
 * Round 190: Intent → preferred module boost map. The TF-IDF scoring
 * gets the right module ~75% of the time but fails on polysemy: "жим"
 * appears in EXERCISE_TECHNIQUE, TRAINING_PRINCIPLES, POWERLIFTING,
 * WOMENS_PROGRAMMING — all score equally high. When the user's intent
 * is "technique question" (form check, not programming), we want
 * EXERCISE_TECHNIQUE to win over POWERLIFTING (which is about meet
 * prep, not form). The priorityModules mechanism (line 1388-1395)
 * appends modules AFTER scoring; this map BOOSTS them DURING scoring
 * so the relative order changes.
 *
 * Boost = ×1.5 (less than the diversity bonus ×1.2 stacked, more than
 * the position bonus ×1.2 alone). Intent-preferred modules can leapfrog
 * a higher-keyword-count module that's wrong-topic.
 */
/**
 * Round 190: Russian fitness synonym graph. The TF-IDF retrieval
 * matches keywords by exact substring — query "ноги" misses keywords
 * like "присед" because they share no characters even though they
 * refer to the same training topic. This map expands the query with
 * synonym keywords BEFORE scoring so query "упражнения на ноги"
 * scores POWERLIFTING (which has "присед" but no "ноги") higher.
 *
 * Each entry maps a USER-FACING term to the canonical KEYWORD set
 * that should also score for that query. Bidirectional intent: if
 * the keyword list contains "присед" and the user types "ноги", we
 * expand "ноги" → ["ноги", "присед", "приседан", "квадрицепс"].
 *
 * Limits: up to 4 synonyms per term to keep score budget bounded.
 * Curated to high-precision pairs only (no semantic stretches).
 */
const KEYWORD_SYNONYMS: Record<string, string[]> = {
  // Lower body
  'ноги': ['присед', 'приседан', 'квадрицепс', 'выпад'],
  'квадрицепс': ['ноги', 'присед'],
  'ягодицы': ['присед', 'тяг', 'выпад', 'ягодиц'],
  'попа': ['ягодицы', 'присед'],
  'икры': ['голень', 'икроножн'],
  'присед': ['ноги', 'квадрицепс', 'присеб'],
  // Upper body push
  'грудь': ['жим', 'отжиман', 'грудн'],
  'плечи': ['жим', 'разводк', 'дельт', 'плечев'],
  'дельты': ['плечи', 'жим'],
  'жим': ['грудь', 'плечи', 'трицепс'],
  // Upper body pull
  'спина': ['тяг', 'подтягиван', 'тяга'],
  'тяга': ['спина', 'становая'],
  'становая': ['тяга', 'спина'],
  'подтягиван': ['спина', 'руки', 'бицепс'],
  // Arms
  'руки': ['бицепс', 'трицепс', 'предплечь'],
  'бицепс': ['руки', 'сгибан'],
  'трицепс': ['руки', 'жим'],
  // Core
  'пресс': ['кор', 'плотн', 'кубик', 'живот'],
  'кор': ['пресс', 'стабильн'],
  // Cardio
  'кардио': ['пульс', 'выносливост', 'аэробн', 'бег'],
  'бег': ['кардио', 'выносливост'],
  // Goals
  'похудение': ['дефицит', 'жиросжиган', 'сушк', 'кутт'],
  'сушка': ['дефицит', 'похудение', 'жиросжиган'],
  'набор': ['массонабор', 'профицит', 'булк', 'гипертрофи'],
  'масса': ['набор', 'мышц', 'гипертрофи'],
  // Recovery
  'восстановление': ['отдых', 'сон', 'разгрузк'],
  'отдых': ['восстановление', 'сон', 'дни покоя'],
  'сон': ['восстановление', 'отдых'],
};

/**
 * Expand a single token into its synonyms (incl. itself, dedup).
 * Used before tokenization so the keyword scoring step sees both
 * the original term AND the synonyms.
 */
function expandSynonyms(token: string): string[] {
  const lower = token.toLowerCase();
  const syns = KEYWORD_SYNONYMS[lower];
  if (!syns) return [lower];
  return Array.from(new Set([lower, ...syns]));
}

const INTENT_MODULE_BOOSTS: Record<string, string[]> = {
  technique_question: ['EXERCISE_TECHNIQUE'],
  program_creation: ['TRAINING_PRINCIPLES', 'PROGRAMMING'],
  workout_modify: ['TRAINING_PRINCIPLES', 'PROGRAMMING'],
  nutrition_query: ['NUTRITION', 'NUTRITION_DATABASE'],
  analytics_query: ['TRAINING_PRINCIPLES'],
  complaint: ['INJURY_AND_REHAB', 'RECOVERY'],
  motivation: ['PSYCHOLOGY'],
  data_logging: ['NUTRITION'],  // most logging is meals
};

function getRelevantKnowledge(
  message: string,
  recentHistory: DeepSeekMessage[] = [],
  userContext?: { goal?: string; gender?: string },
  intent?: string,
): { content: string; topics: string[] } {
  // Build weighted text: current message has highest weight, older messages decay
  const weights = [1.0, 0.5, 0.3, 0.2];
  const textsWithWeights: Array<{ text: string; weight: number }> = [
    { text: message, weight: weights[0] },
  ];

  const userMessages = recentHistory
    .filter((m) => m.role === 'user' && m.content)
    .slice(-3)
    .reverse();
  userMessages.forEach((m, i) => {
    textsWithWeights.push({ text: m.content!, weight: weights[i + 1] || 0.1 });
  });

  // AI-3: precompute the synonym-expanded text once per snippet, before
  // looping over modules. Previously this rebuild ran per-module (25×)
  // for the SAME text — burning ~24× the work needed since the expansion
  // depends only on the snippet, not on which module's keywords we're
  // scoring against. Hoisting saves ~100 set-builds per /chat.
  const preparedTexts = textsWithWeights.map(({ text, weight }) => {
    const lower = text.toLowerCase();
    const words = lower.split(/\s+/);
    const expandedSet = new Set<string>(words);
    for (const w of words) {
      for (const syn of expandSynonyms(w)) expandedSet.add(syn);
    }
    return { text, weight, lower, words, expandedText: Array.from(expandedSet).join(' ') };
  });

  // Score each module with TF-IDF-inspired matching
  const scored = KEYWORD_MAPPINGS
    .map(([module, keywords]) => {
      let score = 0;
      let matchedKeywords: string[] = [];

      for (const { text, weight, lower, words, expandedText } of preparedTexts) {
        for (const keyword of keywords) {
          if (!expandedText.includes(keyword) && !lower.includes(keyword)) continue;

          const idf = getKeywordIDF(keyword);

          // Base score: weight * IDF
          let keywordScore = weight * idf;

          // Exact word match bonus (not just substring): +30%
          if (words.includes(keyword) || words.some(w => w === keyword + 'у' || w === keyword + 'а' || w === keyword + 'ы' || w === keyword + 'ов')) {
            keywordScore *= 1.3;
          }

          // Position bonus: keyword in first 50 chars of message = +20% (user's main intent)
          if (text === message && lower.indexOf(keyword) < 50) {
            keywordScore *= 1.2;
          }

          // Multi-word keyword bonus: phrases like "интервальн голодан" are more specific
          if (keyword.includes(' ')) {
            keywordScore *= 1.5;
          }

          score += keywordScore;
          matchedKeywords.push(keyword);
        }
      }

      // Profile-based implicit relevance boost
      if (userContext?.gender === 'FEMALE' && module === 'WOMENS_PROGRAMMING') score += 2.0;
      if (userContext?.goal === 'WEIGHT_LOSS' && module === 'CUTTING_BULKING') score += 1.5;
      if (userContext?.goal === 'MUSCLE_GAIN' && module === 'CUTTING_BULKING') score += 1.5;
      if (userContext?.goal === 'STRENGTH' && module === 'POWERLIFTING') score += 1.5;
      if (userContext?.goal === 'ENDURANCE' && module === 'ENDURANCE_SPORTS') score += 1.5;

      // Round 190: Intent-aware multiplicative boost. When user's
      // classified intent matches the module's domain, boost by ×1.5
      // so polysemic keywords (e.g. "жим" in technique vs powerlifting)
      // get sorted by topic, not just keyword count. Multiplicative so
      // a module with zero keyword matches doesn't get artificially
      // promoted — it has to have at least some signal first.
      if (intent && score > 0 && INTENT_MODULE_BOOSTS[intent]?.includes(module)) {
        score *= 1.5;
      }

      // Diversity bonus: number of distinct matched keywords matters
      const uniqueMatches = new Set(matchedKeywords).size;
      if (uniqueMatches >= 3) score *= 1.2; // broad topic match = more relevant

      return { module, score, matchedKeywords: uniqueMatches };
    })
    .filter((m) => m.score > 0)
    .sort((a, b) => b.score - a.score);

  // Anti-overlap: avoid selecting modules that share too many keywords with already-selected ones
  const selected: string[] = [];
  const selectedKeywordSets: Set<string>[] = [];

  for (const candidate of scored) {
    if (selected.length >= MAX_KNOWLEDGE_MODULES) break;

    // Check overlap with already selected modules
    const candidateKeywords = new Set(
      KEYWORD_MAPPINGS.find(([m]) => m === candidate.module)?.[1] ?? []
    );

    let maxOverlap = 0;
    for (const existingSet of selectedKeywordSets) {
      let overlap = 0;
      for (const k of candidateKeywords) {
        if (existingSet.has(k)) overlap++;
      }
      const overlapRatio = overlap / Math.min(candidateKeywords.size, existingSet.size);
      maxOverlap = Math.max(maxOverlap, overlapRatio);
    }

    // Skip if >40% keyword overlap with an already selected module.
    // Round 189: was 60% — too permissive. CUTTING_BULKING +
    // NUTRITION_KNOWLEDGE share macros/TDEE/deficit concepts (~50%
    // overlap), and both got selected, wasting ~400 tokens on
    // duplicate content. Lowering to 40% prunes the redundant
    // second module so a third, more diverse one (e.g. RECOVERY
    // for nutrition+training questions) can take its slot.
    if (maxOverlap > 0.4 && selected.length > 0) continue;

    selected.push(candidate.module);
    selectedKeywordSets.push(candidateKeywords);
  }

  const finalSelection = selected.length > 0 ? selected : DEFAULT_MODULES;

  // Round 195: subsection extraction. Knowledge modules are 1-3KB
  // each but the user's question usually maps to ONE topic inside the
  // module. Instead of dumping the full module, find the highest-
  // relevance window of ~600 chars and use only that. Saves ~1KB per
  // request × 100k req/day = ~$1.4/day on Mistral cost. Still falls
  // back to full module if the keyword density is uniform (no clear
  // peak).
  const queryKeywords = collectQueryKeywords(message, recentHistory);
  const content = finalSelection
    .map((name) => {
      const fullText = KNOWLEDGE_MODULES[name];
      if (!fullText) return null;
      // For short modules (<800 chars), don't bother — return full
      if (fullText.length < 800) return fullText;
      // For longer ones, find the best subsection window
      const subsection = extractRelevantSubsection(fullText, queryKeywords);
      return subsection || fullText;
    })
    .filter(Boolean)
    .join('\n\n---\n\n');

  return { content, topics: finalSelection };
}

/**
 * Round 195: collect lowercased keywords from current message + last
 * 3 user messages, expanded with synonyms. Used by extractRelevantSubsection
 * to score windows in module text.
 */
function collectQueryKeywords(message: string, history: DeepSeekMessage[]): string[] {
  const userTexts = [
    message,
    ...history
      .filter((m) => m.role === 'user' && m.content)
      .slice(-3)
      .map((m) => m.content!),
  ];
  const tokens = new Set<string>();
  for (const text of userTexts) {
    const words = text.toLowerCase().split(/\s+/);
    for (const w of words) {
      if (w.length < 3) continue;
      // Strip Russian noise: leading/trailing punctuation
      const clean = w.replace(/[^а-яёa-z]/g, '');
      if (clean.length < 3) continue;
      tokens.add(clean);
      // Add synonyms (defined in KEYWORD_SYNONYMS map)
      for (const syn of expandSynonyms(clean)) tokens.add(syn);
    }
  }
  return Array.from(tokens);
}

/**
 * Round 195: find the highest-relevance window inside a knowledge
 * module. Slides a 600-char window through the text in 100-char
 * steps, scoring each by # of distinct keywords matched. Returns the
 * best-scoring window (with surrounding context) OR null if no
 * window scores meaningfully better than baseline.
 *
 * This keeps relevant teaching while cutting token cost ~60%.
 */
function extractRelevantSubsection(
  fullText: string,
  keywords: string[],
  windowSize = 600,
  step = 100,
): string | null {
  if (keywords.length === 0) return null;
  const lower = fullText.toLowerCase();
  const maxStart = Math.max(0, lower.length - windowSize);
  let bestStart = 0;
  let bestScore = 0;

  // Build candidate start positions: 0, step, 2*step, ..., maxStart
  // The boundary `maxStart` is included even if not divisible by step
  // — without this, keywords near the end of the text get missed when
  // step doesn't divide maxStart evenly (e.g. text 750 chars, window
  // 600, step 100 → maxStart=150 but loop stops at 100).
  const starts = new Set<number>();
  for (let s = 0; s <= maxStart; s += step) starts.add(s);
  starts.add(maxStart);

  for (const start of starts) {
    const window = lower.slice(start, start + windowSize);
    let score = 0;
    for (const kw of keywords) {
      if (window.includes(kw)) score++;
    }
    if (score > bestScore) {
      bestScore = score;
      bestStart = start;
    }
  }

  // If the best window doesn't beat baseline (3+ unique keywords), fall
  // back to full text — better to over-include than miss context.
  if (bestScore < 3) return null;

  // Add a soft prefix indicating this is a partial extract so the AI
  // doesn't mistake the boundary for a paragraph end.
  const start = Math.max(0, bestStart - 50);
  const end = Math.min(fullText.length, bestStart + windowSize + 50);
  const slice = fullText.slice(start, end);
  return start > 0 ? `…${slice}` : slice;
}

