/**
 * Save or update extracted memories in the database.
 * Upsert: if key exists, increment confidence by 0.05 (reward repeated mentions, capped at 1.0 during cleanup); if new, create with 0.7.
 */
// Exported for unit testing in __tests__/cleanupStaleMemories.test.ts.
// Internal use only — no external callers.
export async function cleanupStaleMemories(userId: string): Promise<void> {
  try {
    // Round 97: TTL pruning for soft-confidence stale facts.
    // Memories under confidence 0.85 (= the round-93 strong-qualitative tier
    // and below) that haven't been re-mentioned in 180 days are likely
    // outdated. The user's "люблю приседания" from a year ago might no
    // longer be true; the AI should re-discover it on next mention rather
    // than carry the stale label forever.
    //
    // Hard-confidence facts (≥ 0.85: target_weight_kg, sleep_duration_hours,
    // smoking_status, diet_style, current_weight_kg, height_cm, training_
    // frequency, etc.) are NOT pruned by time alone — they're anchored
    // numeric or behaviour-changing categorical facts that the user
    // intends to be stable. They get refreshed via the upsert path when
    // re-mentioned and only get cut by the top-100 cap.
    const STALE_TTL_MS = 180 * 24 * 60 * 60 * 1000;
    const stalecutoff = new Date(Date.now() - STALE_TTL_MS);

    // Remove low-confidence and clamp over-1.0 entries — independent, run in parallel
    await Promise.all([
      prisma.aIMemory.deleteMany({ where: { userId, confidence: { lt: 0.1 } } }),
      prisma.aIMemory.updateMany({ where: { userId, confidence: { gt: 1.0 } }, data: { confidence: 1.0 } }),
      // TTL prune: soft-confidence + not touched for 180 days.
      prisma.aIMemory.deleteMany({
        where: {
          userId,
          confidence: { lt: 0.85 },
          updatedAt: { lt: stalecutoff },
        },
      }),
    ]);
    // Cap total memories per user at 100 — remove lowest-confidence/oldest beyond the top 100
    const excess = await prisma.aIMemory.findMany({
      where: { userId },
      orderBy: [{ confidence: 'desc' }, { updatedAt: 'desc' }],
      skip: 100,
      select: { id: true },
    });
    if (excess.length > 0) {
      await prisma.aIMemory.deleteMany({ where: { id: { in: excess.map((m) => m.id) } } });
    }
  } catch { /* non-critical */ }
}

// Exported for unit testing (round 115). Internal use only.
export async function saveMemories(userId: string, memories: MemoryExtraction[]): Promise<void> {
  await Promise.all(memories.map(async (mem) => {
    try {
      // Sanitize before persistence. Length-capping alone (the old code)
      // let raw control chars / `[USER]:` injection markers land in the
      // DB row — read paths sanitize, but the row was a future-regression
      // trap waiting for any new reader that forgets the sanitize call.
      const safeKey = sanitizeForPrompt(String(mem.key), 100);
      const safeValue = sanitizeForPrompt(String(mem.value), 500);
      await prisma.aIMemory.upsert({
        where: { userId_key: { userId, key: safeKey } },
        create: {
          userId,
          category: mem.category,
          key: safeKey,
          value: safeValue,
          confidence: mem.confidence,
          source: mem.source,
        },
        update: {
          value: safeValue,
          confidence: { increment: 0.05 },
          source: mem.source,
        },
      });
    } catch (e) {
      logger.error('AIMemory save error:', e);
    }
  }));
}

