// Post-workout AI insights — fast, targeted analysis of a completed session
router.post('/workout-insights', authenticate, async (req: AuthRequest, res: Response) => {
  try {
    const userId = req.userId!;
    // L4 (audit 2026-06-07): this paid-Mistral endpoint had NO per-user control — a free
    // user could burn the budget at 60/min/IP. Cap per-account per-minute.
    if (overPerUserAiRate(userId, 20)) {
      return res.status(429).json({ error: 'Слишком много запросов. Подождите минуту.', code: 'RATE_LIMITED' });
    }
    const bodyParsed = z.object({
      workout: z.object({
        name: z.string().min(1).max(200),
        durationMinutes: z.number().int().finite().min(0).max(1440),
        exercises: z.array(z.object({
          name: z.string().min(1).max(200),
          sets: z.array(z.object({
            weight: z.number().finite().min(0).max(2000).optional(),
            reps: z.number().int().finite().min(0).max(999).optional(),
            completed: z.boolean().optional(),
            rpe: z.number().finite().min(1).max(10).optional(),
          })).max(30),
        })).max(50),
        totalVolume: z.number().finite().min(0).max(1_000_000).optional(),
        notes: z.string().max(2000).optional(),
      }),
    }).safeParse(req.body);
    if (!bodyParsed.success) return res.status(400).json({ error: 'Некорректные данные тренировки' });
    const { workout } = bodyParsed.data;

    const user = await prisma.user.findUnique({ where: { id: userId } });

    // Build a compact workout summary. Exercise names are user-supplied
    // via the request body (Zod max(200) but no char whitelist), so each
    // interpolated string goes through sanitizeForPrompt — same anti-
    // injection rule as round 57's firstName fix.
    const exerciseSummaries = workout.exercises.map((ex) => {
      const safeName = sanitizeForPrompt(ex.name, 100);
      const done = ex.sets.filter((s) => s.completed !== false && (s.weight || s.reps));
      const avgRpe = done.filter((s) => s.rpe).length > 0
        ? (done.reduce((sum, s) => sum + (s.rpe ?? 0), 0) / done.filter((s) => s.rpe).length).toFixed(1)
        : null;
      const best = done.length > 0 ? done.reduce((b, s) => (!b || (s.weight || 0) > (b.weight || 0) ? s : b), done[0]) : null;
      return `${safeName}: ${done.length} подходов${best ? `, лучший ${best.weight} кг × ${best.reps} повт.` : ''}${avgRpe ? `, RPE ${avgRpe}` : ''}`;
    }).join('\n');

    const userGoal = user?.goal ? { WEIGHT_LOSS: 'похудение', MUSCLE_GAIN: 'набор массы', STRENGTH: 'сила', ENDURANCE: 'выносливость', FLEXIBILITY: 'гибкость', GENERAL_FITNESS: 'общая форма' }[user.goal] ?? user.goal : null;

    // Sanitize all user-controlled strings before stitching into the prompt.
    const safeWorkoutName = sanitizeForPrompt(workout.name, 100);
    const safeFirstName = sanitizeForPrompt(user?.firstName ?? 'неизвестен', 60);
    const safeNotes = workout.notes ? sanitizeForPrompt(workout.notes, 500) : '';

    const prompt = `Дай краткий профессиональный анализ тренировки (2-3 абзаца, максимум 200 слов). Будь конкретным и мотивирующим.

ТРЕНИРОВКА: ${safeWorkoutName}
Длительность: ${workout.durationMinutes} мин | Объём: ${Math.round(workout.totalVolume || 0)} кг
Атлет: ${safeFirstName}, цель — ${userGoal || 'не указана'}
${safeNotes ? `Заметки атлета: "${safeNotes}"` : ''}

УПРАЖНЕНИЯ:
${exerciseSummaries}

Ответ строго на русском. Никаких заголовков — просто текст. Структура: 1) что было хорошо, 2) на что обратить внимание, 3) мотивирующий итог.`;

    const text = await generate(prompt, { maxTokens: 512, temperature: 0.7 });
    res.json({ insights: text });
  } catch (e) {
    logger.error('Workout insights error:', e);
    res.status(500).json({ error: 'Не удалось получить анализ' });
  }
});

// ── Voice input — STT via Yandex SpeechKit ─────────────────────────────

/**
 * POST /api/ai/voice — accept short audio recording (≤ 30 sec) from
 * the chat input bar, transcribe via Yandex SpeechKit, return the
 * text so the client can either auto-send or let the user edit first.
 *
 * Audio is uploaded as base64 in JSON (client uses expo-av which
 * produces m4a/AAC by default on Android, LPCM on iOS). Server
 * converts to mono 16 kHz 16-bit LPCM via ffmpeg-static before
 * forwarding to Yandex.
 *
 * Cost: ~6 коп per 15 sec at current Yandex pricing, free up to
 * 5000 requests/month. Single-user dev volume is effectively free.
 */
router.post('/voice', authenticate, async (req: AuthRequest, res: Response) => {
  try {
    const userId = req.userId!;

    // L3 (audit 2026-06-07): per-user per-minute cap on the paid STT endpoint (Yandex
    // bills per call) — complements the per-IP limiter against IP rotation / botnets.
    if (overPerUserAiRate(userId, 10)) {
      return res.status(429).json({ error: 'Слишком много голосовых запросов. Подождите минуту.', code: 'RATE_LIMITED' });
    }

    // ── Subscription gate ───────────────────────────────────────────────
    // Voice STT calls Yandex SpeechKit which costs real money (~6 коп
    // per 15s after the 5K/mo free tier). Gate to paid plans + admins.
    // Admins bypass so the founder / internal testers don't need a sub.
    // Free users are pointed to upgrade via the 402 Payment Required
    // status code (semantically: "this is a paid feature").
    if (req.userRole !== 'ADMIN') {
      const sub = await prisma.subscription.findUnique({
        where: { userId },
        select: { plan: true, status: true, endDate: true },
      });
      const isPaid =
        sub != null &&
        ['pro', 'trainer', 'club'].includes(sub.plan) &&
        (sub.status === 'active' || sub.status === 'cancelled') &&
        (sub.endDate == null || sub.endDate >= new Date());
      if (!isPaid) {
        return res.status(402).json({
          error: 'Голосовой ввод доступен только в Pro подписке',
          code: 'VOICE_REQUIRES_PRO',
        });
      }
    }

    const parsed = z.object({
      audio: z.string().min(100, 'audio too short').max(2_500_000, 'audio too large (>1.8 MB base64)'),
      mimeType: z.string().min(1).max(100).optional(),
    }).safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({ error: parsed.error.errors[0].message });
    }

    const { audio, mimeType } = parsed.data;
    // Strip a data URL prefix if present so the base64 decoder
    // doesn't choke ("data:audio/m4a;base64,XXXXX" → just "XXXXX").
    const b64 = audio.replace(/^data:[^;]+;base64,/, '');
    const buf = Buffer.from(b64, 'base64');
    if (buf.length < 1000) {
      return res.status(400).json({ error: 'Запись слишком короткая' });
    }

    // Pick a hint extension for ffmpeg so it parses the container
    // correctly. Common mimeTypes from expo-av: audio/m4a, audio/mp4,
    // audio/wav, audio/x-caf, audio/3gpp.
    const ext = (mimeType || '').match(/m4a|mp4|wav|3gp|caf|ogg|webm|aac|mp3/i)?.[0] || 'm4a';

    const pcm = await toLpcm16k(buf, ext.toLowerCase());
    if (pcm.length < 1000) {
      return res.status(400).json({ error: 'Не удалось распознать голос (тихая запись)' });
    }

    const result = await yandexTranscribe({ audio: pcm });
    if (!result.ok) {
      logger.warn('[POST /ai/voice] yandex failure', { userId, status: result.status, err: result.error });
      return res.status(result.status === 401 ? 503 : 502).json({
        error: result.error || 'Yandex SpeechKit недоступен',
        code: 'STT_FAILED',
      });
    }
    if (!result.text) {
      return res.json({ text: '' }); // genuine silence — client falls back to manual input
    }
    res.json({ text: result.text });
  } catch (e: any) {
    logger.error('[POST /ai/voice] crashed', e);
    reportError(e, { route: 'ai-voice' });
    res.status(500).json({ error: e?.message || 'Ошибка распознавания голоса' });
  }
});

export { router as aiRouter };

